-- Work that used to be charged after it was done, or not at all. Each pair does the
-- same thing but for that work, so the difference of their work shows its charge.
ONE = { 1 }
MANY = {}
for i = 1, 240 do
  MANY[i] = i
end

local function sink(...)
  return arg.n
end

-- A tail call moves the function and its arguments down to the caller's slot.
function tail(t)
  return sink(unpack(t))
end

function notail(t)
  local n = sink(unpack(t))
  return n
end

-- Returning closes every open upvalue of the frame (and capturing opened them).
function closes(n)
  local cells = {}
  local a, b, c, d, e, f, g, h = 1, 2, 3, 4, 5, 6, 7, 8
  if n > 0 then
    cells[1] = function() return a + b + c + d + e + f + g + h end
  else
    cells[1] = function() return 1 + 2 + 3 + 4 + 5 + 6 + 7 + 8 end
  end
  return cells
end

-- Calling a table through `__call` moves the arguments up to insert the metamethod.
local function handler(self, ...)
  return arg.n
end
local callable = setmetatable({}, { __call = handler })

function meta_call(t)
  local n = callable(unpack(t))
  return n
end

function direct_call(t)
  local n = handler(callable, unpack(t))
  return n
end

-- The error message for an undefined global copies its name.
function long_name()
  return pcall(function() return () end)
end

function short_name()
  return pcall(function() return gy() end)
end
